function deletedPropertyIds(){try{const ids=JSON.parse(localStorage.getItem(DELETED_KEY)||'[]');return Array.isArray(ids)?ids.map(String):[]}catch{return []}}
function writeVerifiedState(key,value){const tempKey=`${key}-write-temp-v1`,payload=JSON.stringify(value);try{window.OTSaveReliability?.preflightStorageWrite?.(localStorage,{[tempKey]:payload,[key]:payload});localStorage.setItem(tempKey,payload);const staged=localStorage.getItem(tempKey);if(staged!==payload)throw Object.assign(new Error('Temporary state write verification failed.'),{code:'temporary-verification'});JSON.parse(staged);localStorage.setItem(key,staged);if(localStorage.getItem(key)!==payload)throw Object.assign(new Error('State write verification failed.'),{code:'temporary-verification'});localStorage.removeItem(tempKey);lastStateWriteFailure=null;return true}catch(error){try{localStorage.removeItem(tempKey)}catch{}lastStateWriteFailure=error;console.warn(`Operation Turtle could not save ${key}.`,error);return false}}
function writeSmallState(key,value){try{const payload=String(value);window.OTSaveReliability?.preflightStorageWrite?.(localStorage,{[key]:payload});localStorage.setItem(key,payload);if(localStorage.getItem(key)!==payload)throw Object.assign(new Error('State write verification failed.'),{code:'temporary-verification'});return true}catch(error){lastStateWriteFailure=error;console.warn(`Operation Turtle could not save ${key}.`,error);return false}}
function saveDeletedPropertyIds(ids){return writeVerifiedState(DELETED_KEY,[...new Set(ids.map(String))])}
function normalizeStartupCollection(value){if(!Array.isArray(value))return null;try{return value.map((item,index)=>normalizeRecord(item,index))}catch{return null}}
function latestValidStartupSnapshot(){let entries=[];try{entries=JSON.parse(localStorage.getItem(RECOVERY_SNAPSHOTS_KEY)||'[]')}catch{};for(const entry of Array.isArray(entries)?entries:[]){let saved=[];try{saved=JSON.parse(entry?.state?.[STORAGE_KEY]||'[]')}catch{};const normalized=normalizeStartupCollection(saved);if(normalized?.length)return normalized}return null}
function loadStartupProperties(){let raw=null;try{raw=localStorage.getItem(STORAGE_KEY);if(raw!==null){const normalized=normalizeStartupCollection(JSON.parse(raw));if(normalized)return mergeSeed(normalized);throw new Error('Stored property collection is malformed or incomplete.')}}catch(error){createRecoverySnapshot('Malformed property store detected during startup');const fallback=latestValidStartupSnapshot();console.warn('Operation Turtle retained stored data and loaded the latest valid recovery snapshot in memory.',error);if(fallback){queueMicrotask(()=>setPersistenceStatus('Recovered last valid snapshot in memory','snapshot'));return mergeSeed(fallback)}queueMicrotask(()=>setPersistenceStatus('Stored data needs recovery review','failed'))}return mergeSeed([])}
