function mergeSeed(old){const deleted=new Set(deletedPropertyIds());const merged=seed.filter(base=>!deleted.has(String(base.id))).map(base=>{const saved=old.find(x=>x.id===base.id)||{};return {...base,...saved,scores:{...base.scores,...(saved.scores||{})},site:{...base.site,...(saved.site||{})},development:{driveway:'unknown',homesite:'unknown',utilities:'unknown',...(base.development||{}),...(saved.development||{})},terrain:saved.terrain||base.terrain||null,destinations:saved.destinations||base.destinations}});return merged.concat(old.filter(x=>!seed.some(s=>s.id===x.id)))}
function recoverySnapshots(){try{const saved=JSON.parse(localStorage.getItem(RECOVERY_SNAPSHOTS_KEY)||'[]');return Array.isArray(saved)?saved:[]}catch{return []}}
function captureOperationTurtleState(){return Object.fromEntries(OT_RECOVERY_STATE_KEYS.map(key=>[key,localStorage.getItem(key)]))}
function createRecoverySnapshot(reason='Property change'){try{const state=captureOperationTurtleState(),raw=state[STORAGE_KEY]||'[]';let collection=[];try{collection=JSON.parse(raw)}catch{}const entry={id:`ot-recovery-${Date.now()}-${Math.random().toString(36).slice(2,7)}`,createdAt:new Date().toISOString(),reason,appVersion:SEED_VERSION,schemaVersion:'canonical-properties-v3-compact',propertyCount:Array.isArray(collection)?collection.length:0,propertyIds:Array.isArray(collection)?collection.map(item=>String(item?.id||'')).filter(Boolean):[],checksum:propertyChecksum(raw),state};const payload=JSON.stringify([entry]);window.OTSaveReliability?.preflightStorageWrite?.(localStorage,{[RECOVERY_SNAPSHOTS_KEY]:payload});localStorage.setItem(RECOVERY_SNAPSHOTS_KEY,payload);if(localStorage.getItem(RECOVERY_SNAPSHOTS_KEY)!==payload)throw Object.assign(new Error('Recovery snapshot verification failed.'),{code:'recovery-snapshot'});lastRecoverySnapshotFailure=null;setPersistenceStatus('Recovery snapshot created','snapshot');return entry}catch(error){lastRecoverySnapshotFailure=error.code==='storage-full'?Object.assign(error,{causeCode:'storage-full',code:'recovery-snapshot'}):error;if(!lastRecoverySnapshotFailure.code)lastRecoverySnapshotFailure.code='recovery-snapshot';if(window.OTDiagnostics?.enabled)console.error('Operation Turtle recovery snapshot failed:',error);return null}}
function snapshot(reason='Property change'){return createRecoverySnapshot(reason)}
window.OTCreateRecoverySnapshot=createRecoverySnapshot;
function textValue(value=''){return typeof value==='string'?value.trim():''}
function isHttpUrl(value=''){try{const url=new URL(String(value));return url.protocol==='http:'||url.protocol==='https:'}catch{return false}}
function isLegacyEmbeddedPhoto(value=''){return /^data:image\/[a-z0-9.+-]+;base64,/i.test(String(value||''))}
function normalizeParcel(value={}){const parcel=value&&typeof value==='object'?value:{};return {...parcel,county:textValue(parcel.county),state:textValue(parcel.state||'TN').toUpperCase().slice(0,2),parcelId:textValue(parcel.parcelId),source:textValue(parcel.source),checkedAt:textValue(parcel.checkedAt),gisUrl:isHttpUrl(parcel.gisUrl)?textValue(parcel.gisUrl):'',recordUrl:isHttpUrl(parcel.recordUrl)?textValue(parcel.recordUrl):'',notes:textValue(parcel.notes)}}
function normalizePhotos(value={}){const photos=value&&typeof value==='object'?value:{},additional=Array.isArray(photos.additional)?photos.additional:[],valid=value=>isHttpUrl(value)||isLegacyEmbeddedPhoto(value);return {...photos,primary:valid(photos.primary)?textValue(photos.primary):'',additional:[...new Set(additional.map(textValue).filter(valid))].slice(0,20)}}
function coordinatesAreUs(value){if(!Array.isArray(value))return false;if(value.length===2&&Number.isFinite(Number(value[0]))&&Number.isFinite(Number(value[1])))return validUsCoordinate(value[1],value[0]);return value.length>0&&value.every(coordinatesAreUs)}
function normalizeParcelGeometry(value){const geometry=value?.type==='Feature'?value.geometry:value;if(!geometry||!['Polygon','MultiPolygon'].includes(geometry.type)||!coordinatesAreUs(geometry.coordinates))return null;return JSON.parse(JSON.stringify(value?.type==='Feature'?value:{type:'Feature',properties:{},geometry}))}
function locationPriority(value={}){const verification=value.locationVerification||value||{},source=`${verification.source||''} ${value.pinQuality||''}`.toLowerCase(),status=String(verification.status||value.locationConfidence||'review').toLowerCase();if(verification.userVerified||/manual|satellite\/map adjustment|user confirmed|manually verified|verified by user/.test(source))return 5;if(/parcel|county gis|assessor/.test(source))return 4;if(/listing/.test(source))return 3;if(status==='high'||status==='verified'||/rooftop|address/.test(source))return 2;return 1}
