async function nominatimNearby(q,lat,lng,delta=.9,limit=8){const west=lng-delta,east=lng+delta,north=lat+delta,south=lat-delta;const url=`https://nominatim.openstreetmap.org/search?format=jsonv2&addressdetails=1&limit=${limit}&countrycodes=us&bounded=1&viewbox=${west},${north},${east},${south}&q=${encodeURIComponent(q)}`;const r=await fetch(url,{headers:{Accept:'application/json'}});if(!r.ok)throw new Error('Search unavailable');return r.json()}
window.refreshRoutes=async function(id){const p=properties.find(x=>x.id===id);if(!p)return;const status=document.getElementById('routeStatus');if(status)status.textContent='Finding major airport and nearby destinations…';const found=[];const airports=MAJOR_AIRPORTS.map(a=>({...a,distanceMiles:haversineMiles(p.lat,p.lng,a.lat,a.lng)})).sort((a,b)=>a.distanceMiles-b.distanceMiles).slice(0,2);airports.forEach((airport,i)=>found.push({label:i===0?'Nearest major airport':'Major airport alternative',name:`${airport.name} (${airport.code})`,address:airport.address,lat:airport.lat,lng:airport.lng,distanceMiles:airport.distanceMiles,checkedAt:new Date().toISOString(),note:airport.tier}));for(const [label,q] of ROUTE_CATEGORIES){try{let results=await nominatimNearby(q,p.lat,p.lng,.85,10);if(!results.length)results=await nominatimNearby(q,p.lat,p.lng,1.5,10);const ranked=results.map(x=>({...x,distanceMiles:haversineMiles(p.lat,p.lng,Number(x.lat),Number(x.lon))})).sort((a,b)=>a.distanceMiles-b.distanceMiles);const best=ranked[0];if(best)found.push({label,name:best.name||best.display_name.split(',')[0],address:best.display_name,lat:Number(best.lat),lng:Number(best.lon),distanceMiles:best.distanceMiles,checkedAt:new Date().toISOString()})}catch{}await new Promise(r=>setTimeout(r,950))}if(found.length){snapshot();p.destinations=found;p.updatedAt=new Date().toISOString();save();openProperty(id)}else if(status)status.textContent='No nearby destinations could be found. Check the connection and try again.'}

