function nextId(){const nums=properties.map(p=>Number(String(p.id||'').match(/\d+/)?.[0]||0));return `OT-${String(Math.max(0,...nums)+1).padStart(3,'0')}`}
function clampScore(v){return Math.max(0,Math.min(100,Math.round(Number(v)||0)))}
function milesBetween(lat1,lng1,lat2,lng2){const r=3958.8,toRad=x=>x*Math.PI/180;const dLat=toRad(lat2-lat1),dLng=toRad(lng2-lng1);const a=Math.sin(dLat/2)**2+Math.cos(toRad(lat1))*Math.cos(toRad(lat2))*Math.sin(dLng/2)**2;return 2*r*Math.asin(Math.sqrt(a))}
function scoreByDistance(miles,best,worst){if(!Number.isFinite(miles))return 50;if(miles<=best)return 95;if(miles>=worst)return 35;return clampScore(95-(miles-best)*(60/(worst-best)))}
function developmentAdjustments(development={}){
  const driveway={existing:2,rough:-7,none:-18,unknown:-5}[development.driveway]??-5;
  const homesite={home:10,pad:6,identified:1,steep:-17,unknown:-6}[development.homesite]??-6;
  const utilities={onsite:5,roadside:1,extension:-7,offgrid:-13,unknown:-4}[development.utilities]??-4;
  return {buildability:driveway+homesite+utilities,value:Math.round(driveway*.55+homesite*.45+utilities*.35)}
}
function terrainBuildabilityScore(terrain){if(!terrain||!Number.isFinite(Number(terrain.maxSlopePct)))return null;const slope=Number(terrain.maxSlopePct),relief=Number(terrain.reliefFt)||0,avg=Number(terrain.avgSlopePct)||0;let score=slope<=5?92:slope<=10?82:slope<=15?70:slope<=22?56:slope<=30?42:28;if(avg>15)score-=7;if(relief>160)score-=10;else if(relief>90)score-=5;return clampScore(score)}
function estimatedDevelopmentTotal(cost={}){const driveway=(Number(cost.drivewayFeet)||0)*32,clearing=(Number(cost.clearingAcres)||0)*6500,electric=(Number(cost.electricFeet)||0)*18,exc={light:12000,moderate:30000,heavy:65000}[cost.excavation]||0,well=cost.well===true||cost.well==='allowance'?16000:0,septic=cost.septic===true||cost.septic==='allowance'?18000:0;return Math.round((driveway+clearing+electric+exc+well+septic)*1.15)}
function infrastructureScore(development={},infrastructure={},beds=0,sqft=0){let s=(beds||sqft)?76:42;const d=development||{},i=infrastructure||{};s+=({existing:12,rough:3,none:-9,unknown:0}[d.driveway]||0)+({home:15,pad:10,identified:4,steep:-8,unknown:0}[d.homesite]||0)+({onsite:12,roadside:6,extension:-4,offgrid:-10,unknown:0}[d.utilities]||0);if(i.well==='existing')s+=8;if(i.septic==='existing')s+=10;if(i.electric==='onsite')s+=6;if(i.clearedSite==='yes')s+=5;if(i.structures==='usable')s+=5;return clampScore(s)}
function readDevelopmentInputs(){return {driveway:document.getElementById('developmentDriveway')?.value||'unknown',homesite:document.getElementById('developmentHomesite')?.value||'unknown',utilities:document.getElementById('developmentUtilities')?.value||'unknown'}}
function writeDevelopmentInputs(development={}){document.getElementById('developmentDriveway').value=development.driveway||'unknown';document.getElementById('developmentHomesite').value=development.homesite||'unknown';document.getElementById('developmentUtilities').value=development.utilities||'unknown'}
