async function analyzeParcelTerrain(){const out=document.getElementById('terrainReadout'),button=document.getElementById('analyzeTerrainBtn');let geometry=null;try{geometry=readParcelGeometryInput()}catch(error){out.textContent=error.message;return}if(!geometry&&editingPropertyId)geometry=window.OTPropertyStore?.getProperty?.(editingPropertyId)?.parcelGeometry||null;if(!geometry){out.textContent='Verify or import the parcel boundary before terrain screening. An address point is not used as the whole property.';return}out.textContent='Sampling elevations across the verified parcel…';button.disabled=true;try{const screen=await window.OTElevation.screenParcelTerrain(geometry,{parcelCertainty:'user-adjusted-parcel',parcelAcreage:Number(document.getElementById('addAcres')?.value)||null});if(!screen.success)throw new Error(screen.failure?.message||'Parcel terrain screening was unavailable.');currentTerrainAnalysis={source:screen.provider,checkedAt:screen.retrievedAt,centerElevationFt:(screen.minimumElevationFeet+screen.maximumElevationFeet)/2,reliefFt:screen.reliefFeet,avgSlopePct:screen.averageSlopePct,maxSlopePct:screen.maximumLocalSlopePct,sampleCount:screen.sampleCount,parcelWide:true,slopeBands:screen.slopeBands,candidateZones:screen.candidateZones};const bands=screen.slopeBands;out.textContent=`Parcel terrain screen: ${screen.sampleCount} samples · ${bands['under-10'].percent}% under 10% slope · ${bands['10-20'].percent}% at 10–20% · ${bands['20-30'].percent}% at 20–30% · ${bands['30-plus'].percent}% at 30%+ · ${screen.candidateZones.length} preliminary candidate zone${screen.candidateZones.length===1?'':'s'}.`;recalculateBaseline()}catch(error){out.textContent=`Terrain analysis could not complete: ${error.message}. The parcel and manual planning inputs were preserved.`}finally{button.disabled=false}}
function defaultDestinations(){return []}
window.setAddPin=function setAddPin(lat,lng,quality='Manually placed pin'){
  const ll=[Number(lat),Number(lng)];
  if(!Number.isFinite(ll[0])||!Number.isFinite(ll[1])||Math.abs(ll[0])<0.0001&&Math.abs(ll[1])<0.0001||ll[0]<18||ll[0]>72||ll[1]<-180||ll[1]>-66){
    const msg=document.getElementById('addMessage');if(msg)msg.textContent='Invalid or non-U.S. coordinates were rejected. No pin was placed.';return false
  }
  if(addPin)map.removeLayer(addPin);
  addPin=L.marker(ll,{draggable:true}).addTo(map).bindTooltip('New property pin',{permanent:false});
 addPin.on('dragend',()=>{const p=addPin.getLatLng();updatePinReadout(p.lat,p.lng,'Manually adjusted pin');window.OTIntegrity?.setManualLocation(p.lat,p.lng,'Manual marker adjustment');recalculateBaseline()});
  updatePinReadout(ll[0],ll[1],quality);
  map.setView(ll,15,{animate:false});
  recalculateBaseline();
  return true;
}
function updatePinReadout(lat,lng,quality){const el=document.getElementById('pinReadout');el.dataset.lat=lat;el.dataset.lng=lng;el.dataset.quality=quality;el.textContent=`Pin: ${Number(lat).toFixed(6)}, ${Number(lng).toFixed(6)} · ${quality}`}
