function parcelDraftFromForm(){const pin=document.getElementById('pinReadout');return {id:editingPropertyId||'parcel-preview',address:document.getElementById('addAddress')?.value.trim()||'',lat:Number(pin?.dataset.lat),lng:Number(pin?.dataset.lng),acres:Number(document.getElementById('addAcres')?.value)||0,parcel:readParcelInputs(),propertyIntelligence:{zillowLand:{}}}}
async function findParcelForForm(){const status=document.getElementById('parcelImportStatus'),button=document.getElementById('findParcelBtn'),draft=parcelDraftFromForm();if(!validUsCoordinate(draft.lat,draft.lng)){status.textContent='Locate the property address before finding its parcel.';return false}status.textContent='Checking the permitted public parcel service…';button.disabled=true;try{const result=await window.OTParcelIntelligence?.acquire?.(draft);if(!result?.success){status.textContent=`Parcel: ${result?.state?.label||'Address Point Only'} · ${result?.failure?.message||'Automatic lookup did not complete.'}`;pendingParcelIntelligence=result?window.OTParcelIntelligence.merge(draft,result).parcelIntelligence:null;return false}const merged=window.OTParcelIntelligence.merge(draft,result);pendingParcelIntelligence=merged.parcelIntelligence;writeParcelInputs(merged.parcel);writeParcelGeometryInput(merged.parcelGeometry);status.textContent=`Parcel: ${result.state.label} · ${result.gisAcres?.toFixed?.(2)||'acreage unavailable'} acres. Review and save to confirm.`;return true}catch(error){status.textContent=`Parcel lookup incomplete: ${error.message}. Use a parcel file or draw/edit the boundary.`;return false}finally{button.disabled=false}}
async function handleParcelFile(event){const file=event.target.files?.[0],status=document.getElementById('parcelImportStatus');if(!file)return;try{const imageLike=/\.(?:pdf|png|jpe?g|webp)$/i.test(file.name),parsed=await window.OTParcelIntelligence.parseBoundaryFile(file);if(parsed.geometry){writeParcelGeometryInput(parsed.geometry);document.getElementById('parcelSource').value=parsed.source;pendingParcelIntelligence={state:parsed.state,source:parsed.source,confidence:parsed.confidence,gisAcreage:parsed.gisAcres,parcelIds:parsed.parcelIds||[],parcels:parsed.parcels||[],acquiredAt:new Date().toISOString(),failure:null};status.textContent=`Parcel coordinate geometry imported from ${file.name} · ${Number(parsed.gisAcres||0).toFixed(2)} calculated acres. Review the outline, then save to confirm.`}else{if(parcelReferenceUrl)URL.revokeObjectURL(parcelReferenceUrl);parcelReferenceUrl=imageLike?URL.createObjectURL(file):'';status.textContent=parsed.failure?.message||'The file did not provide safe coordinate geometry.';if(parcelReferenceUrl){const link=document.createElement('a');link.href=parcelReferenceUrl;link.target='_blank';link.rel='noopener';link.textContent=' Open the uploaded map for visual comparison.';status.append(link)}}}catch(error){status.textContent=`Parcel file not imported: ${error.message}`}finally{event.target.value=''}}
