function applyLocationToProperty(p,candidate={}){if(!p||!validUsCoordinate(candidate.lat,candidate.lng)||!canApplyLocation(p,candidate))return false;p.lat=Number(candidate.lat);p.lng=Number(candidate.lng);p.points={...(p.points||{}),reference:{lat:p.lat,lng:p.lng}};p.pinQuality=String(candidate.pinQuality||candidate.source||'Located property pin');p.locationConfidence=String(candidate.status||candidate.confidence||'review');p.locationVerification={status:p.locationConfidence,source:String(candidate.source||p.pinQuality),userVerified:false,checkedAt:new Date().toISOString(),lat:p.lat,lng:p.lng};p.locationAudit=[...(p.locationAudit||[]),{at:new Date().toISOString(),action:'Research location applied',source:p.locationVerification.source,lat:p.lat,lng:p.lng,accepted:true}];return true}
