function undoLastChange(){try{const old=latestRecoveryProperties();if(!old?.length){setDataMessage('No recovery copy is available yet.');return}if(!createRecoverySnapshot('Before undoing last change'))throw lastRecoverySnapshotFailure||new Error();properties=old.map(normalizeRecord);const restoredSeedIds=new Set(properties.filter(p=>seed.some(s=>String(s.id)===String(p.id))).map(p=>String(p.id)));saveDeletedPropertyIds(deletedPropertyIds().filter(id=>!restoredSeedIds.has(String(id))));reconcileScoutPins();if(!save({reason:'Undo last property change'}))throw new Error();renderMarkers();renderScoutPins();renderList();renderCompare();fitProperties();setDataMessage('Last property change was undone. Any restored seed-property tombstones were cleared.')}catch{setDataMessage('The recovery copy could not be restored.')}}
