function restoreSeedData(){
 if(!confirm('Restore all original Operation Turtle properties? Your current records are protected in a recovery snapshot, and user-created properties will remain.'))return;
 const priorProperties=properties,priorPins=scoutPins,priorTombstones=deletedPropertyIds();snapshot('Before restoring original seed properties');
 const seedIds=new Set(seed.map(p=>String(p.id)));
 const userCreated=properties.filter(p=>!seedIds.has(String(p.id)));
 properties=[...structuredClone(seed),...userCreated];
 saveDeletedPropertyIds(priorTombstones.filter(id=>!seedIds.has(String(id))));
 reconcileScoutPins();if(!save({reason:'Restore original seed properties'})){properties=priorProperties;scoutPins=priorPins;saveDeletedPropertyIds(priorTombstones);saveScoutPins();renderMarkers();renderScoutPins();renderList();renderCompare();setDataMessage('Original properties could not be restored. Your current data was left unchanged.');return}renderMarkers();renderScoutPins();renderList();renderCompare();fitProperties();showStorageHostWarning();setDataMessage('Original properties restored. User-created properties were retained and seed deletion tombstones were cleared.');
}
let deletionInProgress=false,lastDeletedPropertyState=null,deleteUndoTimer=null;
