function clearStoragePressureNotice(){const actions=document.getElementById('storagePressureActions');if(actions)actions.hidden=true}
function showStoragePressureNotice(details){if(!['storage-full','recovery-snapshot','temporary-verification','storage-unavailable'].includes(details?.code))return;const actions=document.getElementById('storagePressureActions');if(actions)actions.hidden=false;storageMessage(details.message||'Storage needs attention. Download a full backup before attempting cleanup.')}
function embeddedPhotoCount(){try{const records=JSON.parse(localStorage.getItem(STORAGE_KEY)||'[]');return Array.isArray(records)?records.reduce((count,record)=>{const photos=[record?.photos?.primary,...(record?.photos?.additional||[])];return count+photos.filter(value=>/^data:image\//i.test(String(value||''))).length},0):0}catch{return 0}}
function renderStorageManagement(){const report=storageReport(),summary=document.getElementById('storageManagementSummary'),rows=document.getElementById('storageManagementReportRows'),details=document.getElementById('storageManagementReport'),photoNotice=document.getElementById('legacyPhotoStorageNotice'),developer=window.OTDiagnostics?.enabled===true;if(summary)summary.textContent=`Operation Turtle uses approximately ${formatStorageBytes(report.totalBytes)} of a conservative ${formatStorageBytes(report.softLimitBytes)} local-storage safety budget.${report.pressure?' Storage pressure is detected: export a full backup before saving again.':''}`;if(rows)rows.innerHTML=report.items.map(item=>`<span><b>${escapeHtml(item.key)}</b> — ${formatStorageBytes(item.bytes)} · ${item.percentage}% · ${item.recordCount} record${item.recordCount===1?'':'s'} · ${escapeHtml(item.classification)}</span>`).join('')||'<span>No Operation Turtle keys are stored for this origin.</span>';if(details)details.hidden=!(developer||report.pressure);const embedded=embeddedPhotoCount();if(photoNotice){photoNotice.hidden=!embedded;photoNotice.textContent=embedded?`${embedded} legacy embedded image reference${embedded===1?'':'s'} detected. They are preserved and never removed automatically; this app accepts lightweight URL references only. Export first, then review any migration separately.`:''}return report}
function downloadStorageDiagnostics(){const report=storageReport(),payload={app:'Operation Turtle',generatedAt:new Date().toISOString(),report,notes:{planning:'Stored inside canonical property records.',photos:'Photo URL references are canonical; no separate image cache exists.',importedBackups:'Imported backup files are not retained in browser storage.',elevationAndGeocoding:'Cached planning elevation and location audit data are property-scoped canonical fields.'}},a=document.createElement('a');a.href=URL.createObjectURL(new Blob([JSON.stringify(payload,null,2)],{type:'application/json'}));a.download=`operation-turtle-storage-diagnostics-${new Date().toISOString().slice(0,10)}.json`;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),500)}
function cleanupStorageKeys(keys,label){const listed=keys.filter(Boolean);if(!listed.length){storageMessage(`No ${label.toLowerCase()} was found.`);return}if(!confirm(`${label}: ${listed.join(', ')}. Canonical properties, planning, scorecards, parcel data, notes, and photo references are excluded. A full backup download will open first. Continue?`))return;window.exportData();try{listed.forEach(key=>localStorage.removeItem(key));storageMessage(`${label} removed: ${listed.join(', ')}.`);renderStorageManagement()}catch(error){storageMessage(saveFailureDetails(error).message)}}
function removeTemporaryVerificationData(){cleanupStorageKeys(Object.keys(localStorage).filter(key=>/-write-temp-v1$/.test(key)),'Temporary verification data')}
function keepNewestRecoverySnapshot(){let entries=[];try{entries=JSON.parse(localStorage.getItem(RECOVERY_SNAPSHOTS_KEY)||'[]')}catch{}const newest=(Array.isArray(entries)?entries:[]).find(entry=>{try{return Array.isArray(JSON.parse(entry?.state?.[STORAGE_KEY]||''))}catch{return false}});if(!newest){storageMessage('No valid recovery snapshot is available to rotate.');return}if(!confirm(`Keep only the newest valid recovery snapshot from ${new Date(newest.createdAt).toLocaleString()}? A full backup download will open first. This does not alter canonical properties.`))return;window.exportData();try{const payload=JSON.stringify([newest]);window.OTSaveReliability?.preflightStorageWrite?.(localStorage,{[RECOVERY_SNAPSHOTS_KEY]:payload});localStorage.setItem(RECOVERY_SNAPSHOTS_KEY,payload);storageMessage('Older recovery snapshots were removed; the newest valid snapshot remains.');renderStorageManagement()}catch(error){storageMessage(saveFailureDetails(error).message)}}
function clearRegenerableCaches(){cleanupStorageKeys(storageReport().items.filter(item=>item.classification==='cache-only').map(item=>item.key),'Regenerable caches')}
window.exportData=function(){const payload={app:'Operation Turtle',backupFormat:'complete-state-v1',version:localStorage.getItem('ot-version')||SEED_VERSION,exportedAt:new Date().toISOString(),state:operationTurtleStorageState()};const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([JSON.stringify(payload,null,2)],{type:'application/json'}));a.download=`operation-turtle-complete-backup-${payload.exportedAt.slice(0,10)}.json`;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),500)}
function validateImportedProperties(value){if(!Array.isArray(value))throw new Error('The backup does not contain a property array.');const normalized=value.map(normalizeRecord),ids=new Set();normalized.forEach(p=>{if(ids.has(p.id))throw new Error(`Duplicate property ID: ${p.id}`);ids.add(p.id)});return normalized}
function validateCompleteBackup(payload){if(payload?.app!=='Operation Turtle'||payload?.backupFormat!=='complete-state-v1'||!payload.state||typeof payload.state!=='object'||Array.isArray(payload.state))throw new Error('This is not a complete Operation Turtle backup.');for(const [key,value] of Object.entries(payload.state))if(!key.startsWith('ot-')||typeof value!=='string')throw new Error(`Invalid backup state entry: ${key}`);if(!(STORAGE_KEY in payload.state))throw new Error('The backup is missing ot-properties.');const normalized=validateImportedProperties(JSON.parse(payload.state[STORAGE_KEY]));if(payload.state[SCOUT_PIN_KEY]!==undefined&&!Array.isArray(JSON.parse(payload.state[SCOUT_PIN_KEY])))throw new Error('The backup contains invalid scout pins.');return {state:payload.state,propertyCount:normalized.length}}
function replaceOperationTurtleState(state){const currentRecovery=localStorage.getItem(RECOVERY_SNAPSHOTS_KEY),changes={};Object.keys(localStorage).filter(key=>key.startsWith('ot-')&&key!==RECOVERY_SNAPSHOTS_KEY).forEach(key=>{changes[key]=null});Object.entries(state).filter(([key])=>key!==RECOVERY_SNAPSHOTS_KEY).forEach(([key,value])=>{changes[key]=value});let combined=[];try{combined=[...JSON.parse(currentRecovery||'[]'),...JSON.parse(state[RECOVERY_SNAPSHOTS_KEY]||'[]')].slice(0,RECOVERY_SNAPSHOT_LIMIT)}catch{combined=JSON.parse(currentRecovery||'[]')}changes[RECOVERY_SNAPSHOTS_KEY]=JSON.stringify(combined);window.OTSaveReliability?.preflightStorageWrite?.(localStorage,changes);Object.keys(localStorage).filter(key=>key.startsWith('ot-')&&key!==RECOVERY_SNAPSHOTS_KEY).forEach(key=>localStorage.removeItem(key));Object.entries(state).filter(([key])=>key!==RECOVERY_SNAPSHOTS_KEY).forEach(([key,value])=>localStorage.setItem(key,value));localStorage.setItem(RECOVERY_SNAPSHOTS_KEY,changes[RECOVERY_SNAPSHOTS_KEY])}
async function importBackupFile(file){const parsed=JSON.parse(await file.text());if(parsed?.backupFormat==='complete-state-v1'){const checked=validateCompleteBackup(parsed);if(!confirm(`Import complete backup from ${new Date(parsed.exportedAt||Date.now()).toLocaleString()}? It contains ${checked.propertyCount} properties and will replace current Operation Turtle data after a recovery snapshot is created.`))return;snapshot('Before importing complete backup');replaceOperationTurtleState(checked.state);location.reload();return}const arr=Array.isArray(parsed)?parsed:parsed?.properties;const normalized=validateImportedProperties(arr);if(!confirm(`Import legacy backup with ${normalized.length} properties? Current properties will first be protected in a recovery snapshot.`))return;snapshot('Before importing legacy backup');properties=normalized;if(Array.isArray(parsed?.scoutPins)){scoutPins=parsed.scoutPins.map(normalizeScoutPin);saveScoutPins()}save();renderMarkers();renderScoutPins();renderList();renderCompare();fitProperties();setDataMessage(`${properties.length} properties imported successfully.`)}
function openSettings(){window.OTOverlayManager?.prepare?.('settings');const panel=document.getElementById('settingsPanel');panel.hidden=false;document.getElementById('versionInfo').textContent=`Operation Turtle 5.0 Preview · Branch: feature/happy-hollow-benchmark-reliability · Build: parcel-recovery-interface · Complete backup format v1`;renderStorageManagement();window.OTOverlayManager?.opened?.('settings')}
function closeSettings(){document.getElementById('settingsPanel').hidden=true}
document.getElementById('settingsBtn').addEventListener('click',openSettings);document.getElementById('closeSettingsBtn').addEventListener('click',closeSettings);document.addEventListener('keydown',event=>{if(event.key==='Escape'&&!document.getElementById('settingsPanel')?.hidden){event.preventDefault();closeSettings();document.getElementById('settingsBtn')?.focus()}});document.getElementById('exportSettingsBtn').addEventListener('click',window.exportData);document.getElementById('storageDownloadBackupBtn')?.addEventListener('click',window.exportData);document.getElementById('storagePressureBackupBtn')?.addEventListener('click',window.exportData);document.getElementById('storagePressureSettingsBtn')?.addEventListener('click',openSettings);document.getElementById('clearTemporaryStorageBtn')?.addEventListener('click',removeTemporaryVerificationData);document.getElementById('rotateRecoveryStorageBtn')?.addEventListener('click',keepNewestRecoverySnapshot);document.getElementById('clearRegenerableCachesBtn')?.addEventListener('click',clearRegenerableCaches);document.getElementById('exportStorageDiagnosticsBtn')?.addEventListener('click',downloadStorageDiagnostics);
document.getElementById('addTopBtn').addEventListener('click',()=>{document.getElementById('compareView')?.classList.remove('desktop-open');const compareButton=document.getElementById('desktopCompareBtn');if(compareButton)compareButton.textContent='Compare';closeDrawer();closePropertyScorecard();editingPropertyId=null;clearListingImport();document.getElementById('addPropertyType').value='raw-land';writeInvestmentInputs(defaultInvestment());document.getElementById('scoreInvestmentFlexibility').value=50;openAddView()});
