document.getElementById('findParcelBtn')?.addEventListener('click',findParcelForForm);document.getElementById('parcelFileInput')?.addEventListener('change',handleParcelFile);document.getElementById('drawParcelFallbackBtn')?.addEventListener('click',()=>document.getElementById('drawBoundaryBtn')?.click());
['scorePrivacy','scoreInfrastructure','scoreBuildability','scoreShopping','scoreAirport','scoreRecreation','scoreValue','scoreInvestmentFlexibility'].forEach(id=>document.getElementById(id).addEventListener('input',updateOverallFromManualScores));
['developmentDriveway','developmentHomesite','developmentUtilities','addPropertyType','investmentDwellingCondition','investmentUtilities','investmentRentalPotential','investmentSubdivisionPotential','investmentOccupyDuringBuild'].forEach(id=>document.getElementById(id).addEventListener('change',recalculateBaseline));
document.getElementById('closeAddBtn').addEventListener('click',closeAddView);document.getElementById('cancelPropertyBtn').addEventListener('click',closeAddView);document.getElementById('dropPinBtn').addEventListener('click',beginDropPin);document.getElementById('savePropertyBtn').addEventListener('click',saveNewProperty);document.getElementById('addPropertyType')?.addEventListener('change',event=>{event.target.dataset.userTouched='true'});
['primaryPhotoUrl','additionalPhotoUrls'].forEach(id=>document.getElementById(id)?.addEventListener('input',renderPhotoFormPreview));document.getElementById('parcelGeometryInput')?.addEventListener('input',renderParcelGeometryStatus);
