// v2.7 Pathfinder — searchable map, custom pins, and layers
const SCOUT_PIN_KEY='ot-scout-pins';
const PIN_CATEGORIES={homesite:['🏠','Homesite'],driveway:['🚜','Driveway'],view:['🌄','View'],water:['💧','Creek / spring'],trail:['🌲','Trail'],gate:['🚪','Gate'],electric:['⚡','Electric'],well:['🚰','Well'],rock:['🪨','Rock / concern'],hunting:['🦌','Hunting'],store:['🛒','Store / reference'],photo:['📷','Photo spot'],note:['📝','General note']};
let scoutPins=[];
try{const saved=JSON.parse(localStorage.getItem(SCOUT_PIN_KEY)||'[]');scoutPins=Array.isArray(saved)?saved.map(normalizeScoutPin):[]}catch{scoutPins=[]}
let pendingScoutLocation=null,editingScoutPinId=null,scoutPinDropMode=false;
function escapeHtml(v=''){return String(v).replace(/[&<>'\"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','\"':'&quot;'}[c]))}
function normalizeScoutPin(pin){return {id:String(pin.id||`SP-${Date.now()}`),propertyId:String(pin.propertyId||''),lat:Number(pin.lat),lng:Number(pin.lng),category:PIN_CATEGORIES[pin.category]?pin.category:'note',title:String(pin.title||PIN_CATEGORIES[pin.category]?.[1]||'Map pin'),notes:String(pin.notes||''),createdAt:String(pin.createdAt||new Date().toISOString()),updatedAt:String(pin.updatedAt||'')}}
function saveScoutPins(){return writeVerifiedState(SCOUT_PIN_KEY,scoutPins)}
function scoutIcon(category){const [emoji]=PIN_CATEGORIES[category]||PIN_CATEGORIES.note;return L.divIcon({className:'scout-div-icon',html:`<div class="scout-pin-symbol"><span>${emoji}</span></div>`,iconSize:[31,31],iconAnchor:[15,29],popupAnchor:[0,-27]})}
function renderScoutPins(){scoutPinGroup.clearLayers();scoutPins.forEach(pin=>{if(!Number.isFinite(pin.lat)||!Number.isFinite(pin.lng))return;const property=properties.find(p=>p.id===pin.propertyId);const marker=L.marker([pin.lat,pin.lng],{icon:scoutIcon(pin.category),title:pin.title}).addTo(scoutPinGroup);marker.bindPopup(`<div class="pin-popup"><h4>${PIN_CATEGORIES[pin.category][0]} ${escapeHtml(pin.title)}</h4>${property?`<p>${escapeHtml(property.id)} · ${escapeHtml(property.name)}</p>`:''}${pin.notes?`<p>${escapeHtml(pin.notes)}</p>`:''}<div class="pin-popup-actions"><button onclick="editScoutPin('${pin.id}')">Edit</button><a href="https://www.google.com/maps/dir/?api=1&destination=${pin.lat},${pin.lng}" target="_blank" rel="noopener">Route ↗</a></div></div>`)});updatePinCount()}
function updatePinCount(){const el=document.getElementById('pinCount');if(el)el.textContent=`${properties.length} properties · ${scoutPins.length} map pins`}
function propertyPinsSection(p){const pins=scoutPins.filter(x=>x.propertyId===p.id);return `<div class="section"><h3>Map pins (${pins.length})</h3>${pins.length?`<div class="pin-list">${pins.map(pin=>`<button class="pin-list-item" onclick="focusScoutPin('${pin.id}')"><span class="pin-emoji">${PIN_CATEGORIES[pin.category][0]}</span><span><b>${escapeHtml(pin.title)}</b><span>${escapeHtml(pin.notes||PIN_CATEGORIES[pin.category][1])}</span></span><span class="pin-arrow">›</span></button>`).join('')}</div>`:'<div class="small">No custom pins attached yet.</div>'}<button class="secondary outline" style="margin-top:8px" onclick="newPinForProperty('${p.id}')">＋ Add property pin</button></div>`}
window.focusScoutPin=function(id){const pin=scoutPins.find(x=>x.id===id);if(!pin)return;closeDrawer();document.querySelector('[data-view="mapView"]').click();map.setView([pin.lat,pin.lng],17);setTimeout(()=>{scoutPinGroup.eachLayer(l=>{const ll=l.getLatLng?.();if(ll&&Math.abs(ll.lat-pin.lat)<1e-7&&Math.abs(ll.lng-pin.lng)<1e-7)l.openPopup()})},120)}
function populatePinForm(){const category=document.getElementById('pinCategory');category.innerHTML=Object.entries(PIN_CATEGORIES).map(([k,v])=>`<option value="${k}">${v[0]} ${v[1]}</option>`).join('');const prop=document.getElementById('pinProperty');prop.innerHTML='<option value="">Global map pin</option>'+properties.map(p=>`<option value="${p.id}">${escapeHtml(p.id)} · ${escapeHtml(p.name)}</option>`).join('')}
function openPinModal({pin=null,propertyId='',lat=null,lng=null,title='',category='note',notes=''}={}){populatePinForm();editingScoutPinId=pin?.id||null;pendingScoutLocation=Number.isFinite(Number(lat))&&Number.isFinite(Number(lng))?L.latLng(Number(lat),Number(lng)):pin?L.latLng(pin.lat,pin.lng):null;document.getElementById('pinCategory').value=pin?.category||category;document.getElementById('pinTitle').value=pin?.title||title;document.getElementById('pinProperty').value=pin?.propertyId||propertyId;document.getElementById('pinNotes').value=pin?.notes||notes;document.getElementById('deleteScoutPinBtn').hidden=!pin;updatePinCoordinateReadout();document.getElementById('pinModal').hidden=false;document.getElementById('pinModalBackdrop').hidden=false}
function closePinModal(){document.getElementById('pinModal').hidden=true;document.getElementById('pinModalBackdrop').hidden=true;if(!scoutPinDropMode){editingScoutPinId=null;pendingScoutLocation=null}}
function updatePinCoordinateReadout(){document.getElementById('pinCoordinates').textContent=pendingScoutLocation?`${pendingScoutLocation.lat.toFixed(6)}, ${pendingScoutLocation.lng.toFixed(6)}`:'Choose Place on map, then tap the location.'}
window.editScoutPin=function(id){const pin=scoutPins.find(x=>x.id===id);if(pin){map.closePopup();openPinModal({pin})}}
window.newPinForProperty=function(id){closeDrawer();openPinModal({propertyId:id,category:'homesite'})}
function beginScoutPinDrop(){scoutPinDropMode=true;document.getElementById('pinModal').hidden=true;document.getElementById('pinModalBackdrop').hidden=true;document.querySelector('[data-view="mapView"]').click();document.body.classList.add('pin-mode');document.querySelector('.map-status').classList.add('pin-instruction');document.querySelector('.map-status').innerHTML='<span>Tap the exact location for this map pin</span><button type="button" onclick="cancelScoutPinDrop()">Cancel</button>'}
window.cancelScoutPinDrop=function(){scoutPinDropMode=false;document.body.classList.remove('pin-mode');restoreMapStatus();openPinModal({pin:editingScoutPinId?scoutPins.find(x=>x.id===editingScoutPinId):null,propertyId:document.getElementById('pinProperty')?.value||'',lat:pendingScoutLocation?.lat,lng:pendingScoutLocation?.lng,title:document.getElementById('pinTitle')?.value||'',category:document.getElementById('pinCategory')?.value||'note',notes:document.getElementById('pinNotes')?.value||''})}
function restoreMapStatus(){const status=document.querySelector('.map-status');status.classList.remove('pin-instruction');status.innerHTML=`<span id="pinCount"></span><button onclick="fitProperties()">Show all</button>`;updatePinCount()}
function saveScoutPin(){if(!pendingScoutLocation){document.getElementById('pinCoordinates').textContent='Place the pin on the map before saving.';return}const existing=scoutPins.find(x=>x.id===editingScoutPinId);const record=normalizeScoutPin({...(existing||{}),id:existing?.id||`SP-${Date.now()}-${Math.random().toString(36).slice(2,6)}`,propertyId:document.getElementById('pinProperty').value,lat:pendingScoutLocation.lat,lng:pendingScoutLocation.lng,category:document.getElementById('pinCategory').value,title:document.getElementById('pinTitle').value.trim()||PIN_CATEGORIES[document.getElementById('pinCategory').value][1],notes:document.getElementById('pinNotes').value.trim(),createdAt:existing?.createdAt||new Date().toISOString(),updatedAt:new Date().toISOString()});if(existing)Object.assign(existing,record);else scoutPins.push(record);saveScoutPins();renderScoutPins();closePinModal();map.setView([record.lat,record.lng],16)}
function deleteScoutPin(){if(!editingScoutPinId)return;if(!confirm('Delete this map pin?'))return;scoutPins=scoutPins.filter(x=>x.id!==editingScoutPinId);saveScoutPins();renderScoutPins();closePinModal()}
map.on('click',e=>{if(!scoutPinDropMode)return;pendingScoutLocation=e.latlng;scoutPinDropMode=false;document.body.classList.remove('pin-mode');restoreMapStatus();openPinModal({pin:editingScoutPinId?scoutPins.find(x=>x.id===editingScoutPinId):null,propertyId:document.getElementById('pinProperty')?.value||'',lat:e.latlng.lat,lng:e.latlng.lng,title:document.getElementById('pinTitle')?.value||'',category:document.getElementById('pinCategory')?.value||'note',notes:document.getElementById('pinNotes')?.value||''})});
const SEARCH_HISTORY_KEY='ot-map-search-history';
function searchCenter(){const openId=document.querySelector('#drawer .prop-id')?.textContent?.trim();const p=properties.find(x=>x.id===openId);return p?L.latLng(p.lat,p.lng):map.getCenter()}
async function runMapSearch(query){const button=document.getElementById('mapSearchBtn');if(button?.disabled)return;const label=button?.textContent||'Search';if(button){button.disabled=true;button.setAttribute('aria-busy','true');button.textContent='Searching…'}try{return await searchMap(query)}finally{if(button){button.disabled=false;button.removeAttribute('aria-busy');button.textContent=label}}}
function rememberSearch(q){let h=[];try{h=JSON.parse(localStorage.getItem(SEARCH_HISTORY_KEY)||'[]')}catch{}h=[q,...h.filter(x=>x.toLowerCase()!==q.toLowerCase())].slice(0,6);writeVerifiedState(SEARCH_HISTORY_KEY,h)}
async function searchMap(query){const input=document.getElementById('mapSearch'),panel=document.getElementById('mapSearchPanel'),q=(query||input.value).trim();if(!q)return;input.value=q;document.querySelector('.map-search-wrap')?.classList.add('has-search');rememberSearch(q);panel.hidden=false;panel.innerHTML='<div class="search-empty">Searching near the current map…</div>';try{const c=searchCenter(),b=map.getBounds();let west=b.getWest(),east=b.getEast(),north=b.getNorth(),south=b.getSouth();const tooWide=(east-west)>3||(north-south)>3;if(tooWide){west=c.lng-1.15;east=c.lng+1.15;north=c.lat+1.05;south=c.lat-1.05}const makeUrl=(bounded,box)=>`https://nominatim.openstreetmap.org/search?format=jsonv2&addressdetails=1&limit=20&countrycodes=us&${bounded?'bounded=1&':''}viewbox=${box.west},${box.north},${box.east},${box.south}&q=${encodeURIComponent(q)}`;let r=await fetch(makeUrl(true,{west,east,north,south}),{headers:{Accept:'application/json'}});if(!r.ok)throw new Error();let results=await r.json();if(!results.length){const box={west:c.lng-2,east:c.lng+2,north:c.lat+1.7,south:c.lat-1.7};r=await fetch(makeUrl(true,box),{headers:{Accept:'application/json'}});if(r.ok)results=await r.json()}results=results.map(x=>({...x,distanceMiles:haversineMiles(c.lat,c.lng,Number(x.lat),Number(x.lon))})).filter(x=>x.distanceMiles<180).sort((a,b)=>a.distanceMiles-b.distanceMiles).slice(0,10);searchResultGroup.clearLayers();if(!results.length){panel.innerHTML='<div class="search-empty">No nearby matches found. Move the map or try a nearby city with the search, such as “Dairy Queen Madisonville TN.”</div>';return}panel.innerHTML=results.map((x,i)=>`<div class="search-result" data-result="${i}"><div><b>${escapeHtml(x.name||x.display_name.split(',')[0])}</b><span>${escapeHtml(x.display_name)}</span></div><span class="distance">${x.distanceMiles.toFixed(1)} mi</span></div>`).join('');results.forEach((x,i)=>{const lat=Number(x.lat),lng=Number(x.lon),title=x.name||x.display_name.split(',')[0];const icon=L.divIcon({className:'scout-div-icon',html:`<div class="search-pin-symbol">${i+1}</div>`,iconSize:[22,22],iconAnchor:[11,11]});L.marker([lat,lng],{icon,title}).addTo(searchResultGroup).bindPopup(`<div class="pin-popup"><h4>${escapeHtml(title)}</h4><p>${escapeHtml(x.display_name)}</p><p><b>${x.distanceMiles.toFixed(1)} miles straight-line from search center</b></p><div class="pin-popup-actions"><button onclick='saveSearchResult(${JSON.stringify({lat,lng,title,notes:x.display_name}).replace(/'/g,"&#39;")})'>Save pin</button><a href="https://www.google.com/maps/dir/?api=1&destination=${lat},${lng}" target="_blank" rel="noopener">Route ↗</a></div></div>`)});panel.querySelectorAll('[data-result]').forEach(el=>el.addEventListener('click',()=>{const i=Number(el.dataset.result),x=results[i];map.setView([Number(x.lat),Number(x.lon)],15);panel.hidden=true;searchResultGroup.getLayers()[i]?.openPopup()}));if(results.length===1)map.setView([Number(results[0].lat),Number(results[0].lon)],15);else map.fitBounds(searchResultGroup.getBounds().pad(.12))}catch{panel.innerHTML='<div class="search-empty">Search is temporarily unavailable. Check your connection and try again.</div>'}}
