function defaultMapLayerState(){return {base:localStorage.getItem('ot-base-layer')||'street',overlays:{properties:document.getElementById('layerProperties')?.checked??true,scoutPins:document.getElementById('layerScoutPins')?.checked??true,searchResults:document.getElementById('layerSearchResults')?.checked??true,parcelBoundaries:document.getElementById('layerParcelBoundaries')?.checked??true,hillshade:document.getElementById('layerHillshade')?.checked??false,contours:document.getElementById('layerContours')?.checked??false}}}
