function currentIntelligenceFilters(){return {minAcres:document.getElementById('minAcresFilter')?.value||'',minTurtleScore:document.getElementById('minTurtleFilter')?.value||'',status:document.getElementById('statusFilter')?.value||'',favorite:document.getElementById('favoriteFilter')?.value==='favorite',county:document.getElementById('countyFilter')?.value||'',minPrice:document.getElementById('minPriceFilter')?.value||'',maxPrice:document.getElementById('maxPriceFilter')?.value||'',maxPricePerAcre:document.getElementById('maxPricePerAcreFilter')?.value||''}}
function renderIntelligenceList(){const target=document.getElementById('propertyList'),engine=window.OTIntelligence;if(!target||!engine)return;const records=properties.map(intelligenceForProperty),filtered=engine.filterProperties(records,currentIntelligenceFilters()),arr=engine.sortProperties(filtered,'turtleScore',{favoritesFirst:true});if(!arr.length){target.innerHTML='<div class="empty-intelligence-state">No properties match the current filters.</div>';return}target.innerHTML=arr.map(property=>{const turtle=engine.getTurtleScore(property),review=engine.dataReview(property),improved=Number(property.beds)||Number(property.baths)||Number(property.sqft),homeStatus=engine.residenceStatus(property),facts=[property.price?money(property.price):'',property.acres?`${property.acres} ac`:'',improved&&property.beds?`${property.beds} bd`:'',improved&&property.baths?`${property.baths} ba`:'',property.sqft?`${Number(property.sqft).toLocaleString()} sq ft`:'',homeStatus==='likely_livable'?'Likely-livable home':homeStatus==='livable'?'Livable home':homeStatus==='condition_unknown'?'Home condition unknown':homeStatus==='non_livable'?'Non-livable home':''].filter(Boolean),star=property.favorite?'★':'☆',turtleLabel=turtle.ratedCount?Math.round(turtle.total):'—',reviewLabel=review.count?`${review.count} ${review.count===1?'item':'items'} need review`:'';return `<article class="property-card intelligence-property-card" onclick="openProperty('${escapeHtml(property.id)}')"><div class="card-row"><div class="card-main"><div class="prop-id">${escapeHtml(property.id)}</div><div class="prop-name">${escapeHtml(preferredPropertyTitle(property.name,property.address))}</div><div class="prop-address">${escapeHtml(property.address)}</div></div><button class="favorite-toggle" type="button" data-favorite-id="${escapeHtml(property.id)}" aria-label="${property.favorite?'Remove':'Add'} favorite" aria-pressed="${property.favorite}">${star}</button><div class="score turtle-score"><b>${turtleLabel}</b><small>Turtle</small></div></div><div class="card-facts">${facts.map(value=>`<span>${escapeHtml(String(value))}</span>`).join('')}</div><div class="chips"><span class="chip">${escapeHtml(displayPropertyStatus(property))}</span><span class="chip">${turtle.ratedCount?`${turtle.ratedCount}/6 scored · ${escapeHtml(turtle.overallConfidence)}`:'Score needs information'}</span>${reviewLabel?`<button class="data-review-indicator" type="button" data-review-id="${escapeHtml(property.id)}">${escapeHtml(reviewLabel)}</button>`:''}</div><div class="card-bottom"><span>${property.favorite?'Favorite':'Property'}</span><button class="open-btn" type="button">Open dossier ›</button></div></article>`}).join('');target.querySelectorAll('[data-favorite-id]').forEach(button=>button.addEventListener('click',event=>{event.stopPropagation();togglePropertyFavorite(button.dataset.favoriteId)}));target.querySelectorAll('[data-review-id]').forEach(button=>button.addEventListener('click',event=>{event.stopPropagation();openPropertyDataReview(button.dataset.reviewId)}))}
function compareDevelopmentEstimate(property){const plan=property.sitePlanning||{},analyses=[...Object.values(plan.drivewayAnalyses||{}),...Object.values(plan.buildSiteAnalyses||{}),...Object.values(plan.utilityAnalyses||{})],planned=analyses.reduce((total,item)=>total+(Number(item?.expected)||0),0);if(planned>0)return planned;const estimate=window.OTPrecision?.estimateCost?.(property.developmentCost||{});return estimate?.items?.length&&Number(estimate.total)>0?Number(estimate.total):null}
