function appendPropertyIntelligence(id){const property=properties.find(item=>item.id===id),overview=document.querySelector('#drawer [data-dossier-tab="Overview"]')||document.querySelector('#drawer .drawer-body'),engine=window.OTIntelligence;if(!property||!overview||!engine||overview.querySelector('[data-property-intelligence]'))return;const turtle=engine.getTurtleScore(intelligenceForProperty(property)),section=document.createElement('section');section.className='section property-intelligence-section';section.dataset.propertyIntelligence='true';section.innerHTML=`<div class="intelligence-section-head"><div><h3>Turtle Score</h3><p class="small">${escapeHtml(displayPropertyStatus(property))}${intelligenceForProperty(property).favorite?' · Favorite':''}</p></div></div><div class="turtle-total"><b>${turtle.ratedCount?`${turtle.total.toFixed(1)}/100`:'Not rated'}</b><span>Confidence ${turtle.confidencePercentage}% · ${escapeHtml(turtle.confidenceStatus)} · ${turtle.ratedCount}/6 categories with evidence</span></div><details class="scorecard-breakdown"><summary>View the six category scores</summary><div class="scorecard-breakdown-grid">${turtle.categories.map(category=>`<div><b>${escapeHtml(category.label)}</b><span>${category.score===null?`Unknown · neutral score effect · ${escapeHtml(category.confidence)}`:`${Number(category.score).toFixed(1)}/10 · ${escapeHtml(category.confidence)}`}</span>${category.reasons.length?`<small>${escapeHtml(category.reasons[0])}</small>`:''}</div>`).join('')}</div></details>`;overview.prepend(section)}
